def is_kawaii_m2(sequence):
    """Checks the kawaii condition for M=2 (only need to check k=2)."""
    # Check if both 1 and 2 are present (implicitly handled by the calling loop)

    # Find first occurrence of 1
    try:
        first_1 = sequence.index(1)
    except ValueError:
        return False # Should not happen if properly filtered

    # Find last occurrence of 2
    try:
        last_2 = len(sequence) - 1 - sequence[::-1].index(2)
    except ValueError:
        return False # Should not happen if properly filtered

    return first_1 < last_2

