def check_kawaii(sequence):
    N = len(sequence)
    if N == 0:
        return False

    # 1. Find the maximum element L
    L = max(sequence)

    # Check Condition 1: If k appears, k-1 must appear.
    present_elements = set(sequence)
    for k in range(2, L + 1):
        if k in present_elements and (k - 1) not in present_elements:
            return False

    # 2. Check Condition 2: F(k-1) < L(k)
    for k in range(2, L + 1):
        # Find first occurrence of k-1
        try:
            f_k_minus_1 = sequence.index(k - 1)
        except ValueError:
            # This should not happen if Condition 1 holds and k is in the sequence
            # But if k is not in sequence, we skip this k (though L implies k is in sequence)
            continue 

        # Find last occurrence of k
        try:
            # Calculate last index by iterating backwards
            l_k = N - 1 - sequence[::-1].index(k)
        except ValueError:
            # k does not appear in the sequence
            continue

        if k in present_elements:
            if f_k_minus_1 >= l_k:
                return False

    return True

